$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'backend\src\routes\operaciones.js')) { Write-Host 'Corre este script desde la carpeta Contratos (raiz del repo).' -ForegroundColor Red; exit 1 }
function Write-FileFromBase64([string]$Path,[string]$B64){
  [IO.File]::WriteAllBytes((Join-Path (Get-Location) $Path), [Convert]::FromBase64String(($B64 -replace '\s',''))); Write-Host "OK $Path" }
